-- V007: read-only player world intel, separate from the actual city/state tables.
-- An entry is never visible just because it is stored. No autogenerated content.
-- All disclosure is explicit through scoped grants, except a player's own influence.
CREATE UNIQUE INDEX cities_world_city_identity ON cities(world_id, city_id);

CREATE TABLE map_city_discoveries (
  world_id text NOT NULL,
  city_id uuid NOT NULL,
  viewer_account_id uuid NOT NULL,
  discovered_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (world_id, city_id, viewer_account_id),
  FOREIGN KEY (world_id, city_id) REFERENCES cities(world_id, city_id) ON DELETE CASCADE,
  FOREIGN KEY (world_id, viewer_account_id)
    REFERENCES world_memberships(world_id, account_id) ON DELETE CASCADE
);

CREATE TABLE map_world_sites (
  site_id uuid PRIMARY KEY,
  world_id text NOT NULL REFERENCES worlds(world_id) ON DELETE CASCADE,
  kind text NOT NULL CHECK(kind IN ('sphinx','obelisk','dolmen','portal','relic','special')),
  x integer NOT NULL CHECK(x>=1),
  y integer NOT NULL CHECK(y>=1),
  label text NOT NULL CHECK(length(label) BETWEEN 1 AND 100),
  source_ref text NOT NULL CHECK(length(source_ref) BETWEEN 3 AND 255),
  UNIQUE(world_id,site_id)
);
CREATE INDEX map_world_sites_location ON map_world_sites(world_id,x,y);

CREATE TABLE map_site_discoveries (
  world_id text NOT NULL,
  site_id uuid NOT NULL,
  viewer_account_id uuid NOT NULL,
  discovered_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(world_id,site_id,viewer_account_id),
  FOREIGN KEY(world_id,site_id)
    REFERENCES map_world_sites(world_id,site_id) ON DELETE CASCADE,
  FOREIGN KEY(world_id,viewer_account_id)
    REFERENCES world_memberships(world_id,account_id) ON DELETE CASCADE
);

-- Precomputed territorial control, not a newly invented influence formula.
CREATE TABLE map_influence_cells (
  world_id text NOT NULL REFERENCES worlds(world_id) ON DELETE CASCADE,
  x integer NOT NULL CHECK(x>=1),
  y integer NOT NULL CHECK(y>=1),
  controller_account_id uuid NOT NULL,
  source_ref text NOT NULL CHECK(length(source_ref) BETWEEN 3 AND 255),
  observed_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(world_id,x,y),
  FOREIGN KEY(world_id,controller_account_id)
    REFERENCES world_memberships(world_id,account_id)
);
CREATE TABLE map_influence_discoveries (
  world_id text NOT NULL,
  x integer NOT NULL,
  y integer NOT NULL,
  viewer_account_id uuid NOT NULL,
  discovered_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(world_id,x,y,viewer_account_id),
  FOREIGN KEY(world_id,x,y)
    REFERENCES map_influence_cells(world_id,x,y) ON DELETE CASCADE,
  FOREIGN KEY(world_id,viewer_account_id)
    REFERENCES world_memberships(world_id,account_id) ON DELETE CASCADE
);
